var unit='m',tabs=document.getElementById('tabs');
tabs.addEventListener('click',function(e){
  var b=e.target.closest('button');if(!b)return;
  [].forEach.call(tabs.querySelectorAll('button'),function(x){x.classList.remove('active');});
  b.classList.add('active');unit=b.getAttribute('data-u');
  document.getElementById('metric').style.display=unit==='m'?'':'none';
  document.getElementById('imperial').style.display=unit==='i'?'':'none';
  calc();WT.resize();
});
function n(id){var v=parseFloat(document.getElementById(id).value);return isNaN(v)?0:v;}
function calc(){
  var hM,wKg;
  if(unit==='m'){hM=n('cm')/100;wKg=n('kg');}
  else{hM=(n('ft')*12+n('inch'))*0.0254;wKg=n('lb')*0.45359237;}
  var note=document.getElementById('note');
  if(hM<=0.5||wKg<=0){
    document.getElementById('bmi').textContent='--';
    document.getElementById('cls').textContent='--';
    note.textContent='Enter a realistic height and weight to see your result.';
    return;
  }
  var bmi=wKg/(hM*hM);
  var b=Math.round(bmi*10)/10;
  var cls,tip;
  if(bmi<18.5){cls='Underweight';tip='A BMI under 18.5 is classed as underweight.';}
  else if(bmi<25){cls='Healthy weight';tip='A BMI between 18.5 and 24.9 is the healthy range for most adults.';}
  else if(bmi<30){cls='Overweight';tip='A BMI between 25 and 29.9 is classed as overweight.';}
  else {cls='Obese';tip='A BMI of 30 or above is classed as obese.';}
  document.getElementById('bmi').textContent=b;
  document.getElementById('cls').textContent=cls;
  var lo=18.5*hM*hM,hi=24.9*hM*hM,rangeText;
  if(unit==='m'){rangeText=(Math.round(lo*10)/10)+' to '+(Math.round(hi*10)/10)+' kg';}
  else{rangeText=Math.round(lo/0.45359237)+' to '+Math.round(hi/0.45359237)+' lb';}
  document.getElementById('range').textContent=rangeText;
  var pos=Math.max(0,Math.min(100,(bmi-13)/(40-13)*100));
  document.getElementById('dot').style.left=pos+'%';
  note.textContent=tip+' BMI is a general guide only and does not measure body fat directly.';
}
['cm','kg','ft','inch','lb'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});
calc();
